class TestModel():

    def test_sesstionTest(self):
        for x in range(1):
            options = webdriver.ChromeOptions()
            options.add_argument('ignore-certificate-errors')
            options.add_argument('--start-maximized')
            options.add_experimental_option('detach',True)
            self.driver = webdriver.Chrome(chrome_options=options)
            self.driver.implicitly_wait(waitTime)
            self.URL = emsURL
            self.vars = {}
            self.driver.get(self.URL)
            self.driver.find_element(By.ID, "name").send_keys(adminName)
            self.driver.find_element(By.ID, "passwd").clear()
            self.driver.find_element(By.ID, "passwd").send_keys(adminPwd)
            self.driver.find_element(By.ID, "signin").click()
            WebDriverWait(self.driver, 180).until(EC.visibility_of_element_located((By.ID,"index_t_userName")))
            self.driver.quit()





